"""Vendored Grimme DFT-D4 reference parameters (BJ damping, EEQ charges).

Generated by scripts/gen_d4_params.py from tad-dftd4 / tad-multicharge /
tad-mctc (dftd4/tad-dftd4 on GitHub), a verbatim PyTorch port of S. Grimme's
dftd4. Physical reference data from Caldeweyher, Bannwarth, Grimme, J. Chem.
Phys. 150, 154122 (2019). Units are atomic (Bohr, Hartree); the caller
converts at the boundary.

The pairwise reference-C6 tables C6REF are charge-independent (the reference
polarizabilities are built from fixed reference charges) and are precomputed
with tad-dftd4's Casimir-Polder integration. Runtime charge dependence enters
only through the EEQ partial charges and the zeta weighting of the references.

Covered subset (extend SUBSET in the generator to add more, then re-run
the D4 dispersion tests):
H, He, Li, Be, B, C, N, O, F, Ne, Na, Mg, Al, Si, P, S, Cl, Ar, K, Ca, Sc, Ti, V, Cr,
Mn, Fe, Co, Ni, Cu, Zn, Ga, Ge, As, Se, Br, Kr.
"""

